const token = $json.access_token;
const pending = $('Find Pending TX').all();
const shortcode = $env.MPESA_SHORTCODE || '174379';
const passkey = $env.MPESA_PASSKEY;
const baseUrl = $env.MPESA_BASE_URL || 'https://sandbox.safaricom.co.ke';

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const timestamp =
  now.getFullYear().toString() + pad(now.getMonth()+1) + pad(now.getDate()) +
  pad(now.getHours()) + pad(now.getMinutes()) + pad(now.getSeconds());
const password = Buffer.from(shortcode + passkey + timestamp).toString('base64');

return pending.map(p => ({
  json: {
    url: `${baseUrl}/mpesa/stkpushquery/v1/query`,
    authHeader: `Bearer ${token}`,
    checkout_request_id: p.json.checkout_request_id,
    payload: {
      BusinessShortCode: parseInt(shortcode, 10),
      Password: password,
      Timestamp: timestamp,
      CheckoutRequestID: p.json.checkout_request_id
    }
  }
}));
